    "Address": definitions.Address,
    "BookingPolicies": definitions.BookingPolicies,
    "BookingRoom": definitions.BookingRoom,
    "BookingStatus": definitions.BookingStatus,
    "BookingTransaction": definitions.BookingTransaction,
    "CancellationPenalty": definitions.CancellationPenalty,
